import { useRef, useEffect } from "react";
import { View, Text, Animated } from "react-native";

export default function App() {
  const opacity = useRef(new Animated.Value(0)).current;       // giá trị hoạt ảnh, không gây render lại

  useEffect(() => {
    Animated.timing(opacity, { toValue: 1, duration: 150, useNativeDriver: false }).start();
  }, []);

  return (
    <Animated.View testID="box" style={{ opacity, padding: 16, backgroundColor: "#bae6fd" }}>
      <Text>Hiện dần</Text>
    </Animated.View>
  );
}

