import { useRef, useEffect } from "react";
import { Animated } from "react-native";

export default function App() {
  const v = useRef(new Animated.Value(0)).current;
  useEffect(() => {
    Animated.timing(v, { toValue: 1, duration: 150, useNativeDriver: false }).start();
  }, []);
  const width = v.interpolate({ inputRange: [0, 1], outputRange: [50, 200] });
  return <Animated.View testID="bar" style={{ height: 20, width, backgroundColor: "teal" }} />;
}
